import{_ as r}from"./chunks/inter_core_sync_scenario_example.Cgh3NH_Y.js";import{_ as e}from"./chunks/block_subblock_relationship_3510.Dld0RPG9.js";import{_ as o,o as _,a as c,b as a}from"./app.C41L12d5.js";const k=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"同步控制","link":"/api/SIMD-API/basic_api/sync_control/sync_control"},{"text":"核间同步","link":"/api/SIMD-API/basic_api/sync_control/inter_core_sync/inter_core_sync"},{"text":"核间同步能力概述","link":"/api/SIMD-API/basic_api/sync_control/inter_core_sync/inter_core_sync_overview"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/sync_control/inter_core_sync/inter_core_sync_overview.md","filePath":"api/SIMD-API/basic_api/sync_control/inter_core_sync/inter_core_sync_overview.md","lastUpdated":1787050286000}'),d={name:"api/SIMD-API/basic_api/sync_control/inter_core_sync/inter_core_sync_overview.md"};function i(s,t,I,l,n,b){return _(),c("div",null,[...t[0]||(t[0]=[a('<div><article class="markdown-body"><h1>核间同步能力概述<span id="ZH-CN_TOPIC_0000002555803758"></span></h1><p>核间同步的使用场景通常是：一个核计算所依赖的数据，需要等待其他相关核的计算全部完成后才能获取。</p><p>以图1为例，AIC需要依赖于AIV的ReduceSum计算结果。由于整体矢量较大，必须拆分为多个部分，由每个AIV分别完成部分计算。每个AIV将其部分计算结果通过原子累加写入GM。AIC需要读取的必须是所有AIV均完成累加后的最终结果，因此需要通过核间同步来保证AIC读取ReduceSum结果时的时序正确性。</p><p><strong>图1</strong> 核间同步业务场景示例图（AIC:AIV为1 : 2）<span id="zh-cn_topic_0000002542605351_fig1180684585013"></span><br><img src="'+r+'" alt title="核间同步业务场景示例图（AIC-AIV为1-2）"></p><p>AIC/AIV多核结构如下图2所示，AIC/AIV按group划分。一个group内细分block及subblock，block与subblock比例为1:N（N&gt;=1），block表示多少个“主核”，subblock表示一个“主核”带多少个“从核”。</p><p>算子按计算特征可分为三类：Cube算子（矩阵计算）、Vector算子（矢量计算）和Mix算子（同时包含矩阵和矢量计算）。如表1所示，算子类型决定了其所需的核间同步方式和可选的group配置模式。其中Mix算子通过函数修饰符指定AIC与AIV的block/subblock关系；Cube算子和Vector算子为单类核执行，不涉及block/subblock划分。AIV为block且AIC为subblock的配置（即Vector核为主、Cube核为辅的模式）当前不支持。表2总结了核间同步接口及其支持的同步场景。</p><p><strong>图2</strong> block和subblock之间关系（灰色部分表示一个group，即1个block和N个subblock）<span id="zh-cn_topic_0000002542605351_fig52727114018"></span><img src="'+e+'" alt title="（NPU架构版本3510）block和subblock之间关系（灰色部分表示一个group，即1个block和N个subblock）"></p><p><strong>表1</strong> group配置<span id="zh-cn_topic_0000002542605351_table17238184964217"></span></p><table><thead><tr><th>算子类型</th><th>函数修饰符</th><th>核函数（Kernel）类型</th><th>block/subblock</th><th>1 ：N</th></tr></thead><tbody><tr><td>Cube算子</td><td>__cube__</td><td>KERNEL_TYPE_AIC_ONLY</td><td>AIC为block，无subblock</td><td>不涉及</td></tr><tr><td>Vector算子</td><td>__vector__</td><td>KERNEL_TYPE_AIV_ONLY</td><td>AIV为block，无subblock</td><td>不涉及</td></tr><tr><td>Mix算子</td><td>__mix__(1, 0)</td><td>KERNEL_TYPE_MIX_AIC_1_0</td><td>AIC为block，无subblock</td><td>不涉及</td></tr><tr><td>Mix算子</td><td>__mix__(0, 1)</td><td>KERNEL_TYPE_MIX_AIV_1_0</td><td>AIV为block，无subblock</td><td>不涉及</td></tr><tr><td>Mix算子</td><td>__mix__(1, 1)</td><td>KERNEL_TYPE_MIX_AIC_1_1</td><td>AIC为block，AIV为subblock</td><td>1：1</td></tr><tr><td>Mix算子</td><td>__mix__(1, 2)</td><td>KERNEL_TYPE_MIX_AIC_1_2</td><td>AIC为block，AIV为subblock</td><td>1：2</td></tr></tbody></table><p><strong>表2</strong> 支持的核间同步场景</p><table><thead><tr><th>接口名称</th><th>核间同步场景概述</th><th>同步类别</th></tr></thead><tbody><tr><td><a href="CrossCoreSetFlag_ISASI.html">CrossCoreSetFlag</a>/<a href="CrossCoreWaitFlag_ISASI.html">CrossCoreWaitFlag</a></td><td>多个AIC或AIV之间的同步控制。CrossCoreSetFlag负责发送通知，CrossCoreWaitFlag负责阻塞直到CrossCoreSetFlag发送通知。<br>支持以下同步场景：<br>•（模式0）同步等待全部AIC或者同步等待全部AIV执行结束。<br>•（模式1）单个AI Core内，全部AIV之间的同步。<br>•（模式2）单个AI Core内，AIC与全部AIV之间的同步。<br>•（模式4）单个AI Core内，AIC核与单个AIV之间同步。</td><td>硬件同步</td></tr><tr><td><a href="IBSet.html">IBSet</a>/<a href="IBWait.html">IBWait</a></td><td>IBSet和IBWait配合使用，用于一对AIV间的同步：等待核调用IBWait阻塞本核后续指令的执行，被等待核调用IBSet通知等待核解除阻塞。上述同步过程的原理如下：被等待核中调用IBSet，通过将值1写入全局内存中某块地址来通知等待核；而等待核中调用IBWait，持续读取全局内存中相应地址块的值，直到其值变为1。</td><td>软件同步</td></tr><tr><td><a href="SyncAll.html">SyncAll</a></td><td>用于多个核之间的同步控制，支持以下同步场景：<br>•纯Vector算子的全核同步，可参考<a href="key_features.html">CrossCoreSetFlag的模式0</a>。<br>•融合算子的全核同步，一次性实现三个核间同步能力（参考<a href="key_features.html">CrossCoreSetFlag的关键特性说明</a>）：首先完成单个AI Core内，AIC与全部AIV之间的同步（AIC等AIV）；接着完成多个AI Core间，所有AIC的同步；最后完成单个AI Core内，所有AIV与AIC同步（AIV等AIC）。</td><td>硬件同步</td></tr><tr><td><a href="SyncAll.html">SyncAll</a></td><td>仅支持纯Vector算子的多核（参与同步的核数可通过入参指定）同步。每一个AIV都向全局内存对应位置写入信号值1，接着每一个AIV都持续轮询全局内存中所有AIV对应的信号值，直到所有AIV核对应的信号值都变为1。</td><td>软件同步</td></tr><tr><td><a href="InitDetermineComputeWorkspace.html">InitDetermineComputeWorkspace</a>/<a href="NotifyNextBlock.html">NotifyNextBlock</a>/<a href="WaitPreBlock.html">WaitPreBlock</a></td><td>• InitDetermineComputeWorkspace、NotifyNextBlock和WaitPreBlock三个接口必须组合使用，能够确保多个AIV核严格按照blockIdx的升序执行，适用于要求确定性计算的场景。<br>• InitDetermineComputeWorkspace初始化GM共享内存的值，完成初始化后才可以调用NotifyNextBlock和WaitPreBlock。<br>• NotifyNextBlock通过写全局内存来通知其他核当前核已执行完成，其他核可以继续往下执行；WaitPreBlock通过读取全局内存，判断当前核是否可以继续往下执行。</td><td>软件同步</td></tr></tbody></table></article></div>',1)])])}const h=o(d,[["render",i]]);export{k as __pageData,h as default};
